-- Batch 04: reviewed internal project material pages, immutable source hashes.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';
SET LOCAL application_name='colliers_ai_backfill_20261125_v5';
DO $fill$
DECLARE r record; n int:=0; old_count int; changed int; ev uuid; now_ts timestamptz; read_value jsonb; source_row jsonb; sub_batch int:=4; expected_before int:=64; expected_added int:=17;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtext('ai_building_field_backfill_20261125_v5_100'));
 SELECT count(*) INTO old_count FROM public.audit_logs WHERE action_type='AI_FIELD_FILL' AND details->>'batch_ref'='ai_building_field_backfill_20261125_v5_100';
 IF old_count<>expected_before OR old_count+expected_added>100 THEN RAISE EXCEPTION 'batch sequence guard: %',old_count; END IF;
 -- Serialize the brief data transaction against other writes, not normal reads.
 LOCK TABLE public.buildings,public.building_brochure_data,public.building_data_field_provenance IN SHARE ROW EXCLUSIVE MODE;
 LOCK TABLE public.project_material_library,public.project_material_library_pages IN SHARE MODE;
 FOR r IN
 WITH specs AS (SELECT * FROM jsonb_to_recordset($spec$[{"lib":"9d4c9ef4-f616-511d-b043-c917cc2eb3d0","name":"Z3东环捌号","pg":1,"hash":"460247eb08012106f2131ebc704418dcf15cf242beedf0cdcafacf69ecd20f52","f":"address","type":"text","unit":"address","pat":"(北京市朝阳区东三环中路8号)","note":"项目推介封面，规划项目地址","mult":1},{"lib":"9d4c9ef4-f616-511d-b043-c917cc2eb3d0","name":"Z3东环捌号","pg":13,"hash":"531a76c878b6b95be44038016a3ac47e6bbf904409d440b3f517bb8f9a481378","f":"building_height","type":"numeric","unit":"m","pat":"17[.]5[[:space:]]*万㎡[[:space:]]*11[.]7[[:space:]]*万㎡[[:space:]]*1[.]75[[:space:]]*万㎡[[:space:]]*([0-9]+)[[:space:]]*m[[:space:]]*45","note":"项目概览表头建筑高度；设计140m，非45m中庭","mult":1},{"lib":"9d4c9ef4-f616-511d-b043-c917cc2eb3d0","name":"Z3东环捌号","pg":18,"hash":"2bb1609a5b6ae834c302e55ea4cfde5df6e580b7d5ae3d7d28d45be43a007e71","f":"column_free","type":"boolean","unit":"boolean","pat":"(超阔无柱化空间)","note":"未入市项目办公区设计能力，不代表每个单元无柱","mult":1},{"lib":"9d4c9ef4-f616-511d-b043-c917cc2eb3d0","name":"Z3东环捌号","pg":35,"hash":"a84dfb10bc5bb1fc02c158b6e96c7f518726b697b32fd62dda54333f25c45ea0","f":"clear_height","type":"numeric","unit":"m","pat":"层高4[.]5m，净高([0-9.]+)m","note":"设计标准层净高","mult":1},{"lib":"9d4c9ef4-f616-511d-b043-c917cc2eb3d0","name":"Z3东环捌号","pg":35,"hash":"a84dfb10bc5bb1fc02c158b6e96c7f518726b697b32fd62dda54333f25c45ea0","f":"delivery_standard","type":"text","unit":"configuration","pat":"交付标准[[:space:]]+(吊顶加灯具，铺设150mm高端高负荷度架空地板，具有超高强度，且环保可回收，室内安装窗帘)","note":"拟交付标准，不声称已交付","mult":1},{"lib":"9d4c9ef4-f616-511d-b043-c917cc2eb3d0","name":"Z3东环捌号","pg":9,"hash":"ec0bc4a80dc2ae02f6cebc9ee6b0726709d465ec109c7c1e32d3571784406a3b","f":"metro_access","type":"text","unit":"nearby_station","pat":"(200米即达1号线与10号线国贸站)","note":"项目推介既有地铁位置描述，不填未开通28号线；距离为资料值","mult":1},{"lib":"3ec52395-8d61-598a-a96b-8a75bafe9e37","name":"懋源曜中心","pg":3,"hash":"d4bbcb74661f9c7f78015db99ba2df626a9a383f3395edf66917af08bce14f8a","f":"metro_access","type":"text","unit":"nearby_station","pat":"(地铁10号线、12号线、机场线三条轨道交通交汇，地铁口距离本项目仅50m)","note":"规划项目区位，原资料描述","mult":1},{"lib":"3ec52395-8d61-598a-a96b-8a75bafe9e37","name":"懋源曜中心","pg":5,"hash":"94b3f2091a58f3157d9bf0697dcdd56f36a1503255480955da368142c67b7a78","f":"gfa_office","type":"numeric","unit":"m2","pat":"其中办公约([0-9.]+)㎡","note":"规划办公建筑面积约37902㎡，不等同于可租面积","mult":1},{"lib":"3ec52395-8d61-598a-a96b-8a75bafe9e37","name":"懋源曜中心","pg":6,"hash":"41024ff59392e4339195f44ab9d9b73900ec45549dba1f38b0dfba38853c56f8","f":"facade_type","type":"text","unit":"configuration","pat":"(晶体状渐变的三角形单元式幕墙体系)","note":"设计外立面，非已建实测","mult":1},{"lib":"3ec52395-8d61-598a-a96b-8a75bafe9e37","name":"懋源曜中心","pg":20,"hash":"6ff1fda3051392af6225d9d619a8c6f41d323e775b8f162eae11e3ee357941c4","f":"power_system","type":"text","unit":"configuration","pat":"供电方式[[:space:]]+(市政双路供电＋柴油发电机重要负荷供电，三重保险)","note":"拟设计供电方式","mult":1},{"lib":"3ec52395-8d61-598a-a96b-8a75bafe9e37","name":"懋源曜中心","pg":20,"hash":"6ff1fda3051392af6225d9d619a8c6f41d323e775b8f162eae11e3ee357941c4","f":"elevator_zones","type":"text","unit":"configuration","pat":"(A塔：客梯5部 / 转换梯2部 / 餐梯2部[[:space:]]+电梯数量[[:space:]]+消防电梯1部 / 消防电梯兼货梯1部 / 扶梯2部[[:space:]]+B塔：客梯5部 / 转换梯2部 / 消防电梯1部)","note":"原设计资料区分两塔及客梯/转换/消防；参数暂定，未宣称安装完成","mult":1},{"lib":"071dd93a-b56d-509c-89fe-7b01f2e822b2","name":"丰科中心","pg":1,"hash":"a249a9a05710c3ccdb58d5d591758f08d7463bc1b59c6c653be3ef3c03dabf6b","f":"name_en","type":"text","unit":"name","pat":"(FUTURE CENTRE)","note":"已审阅项目推介封面官方英文名称","mult":1},{"lib":"071dd93a-b56d-509c-89fe-7b01f2e822b2","name":"丰科中心","pg":5,"hash":"2bef57077e521824e9ba6a4017c5a20becc9429c47bc1133bb5e98dd618b9c43","f":"gfa_total","type":"numeric","unit":"m2","pat":"总建[[:space:]]*筑[[:space:]]*面[[:space:]]*积[[:space:]]*约([0-9.]+)万㎡","note":"四栋楼组成整个丰科中心约15万㎡；非单栋","mult":10000},{"lib":"071dd93a-b56d-509c-89fe-7b01f2e822b2","name":"丰科中心","pg":9,"hash":"e786215007ad20ae05df8018544565bf4f3970ad088cf4daca8c3f3cf1700ced","f":"facade_type","type":"text","unit":"configuration","pat":"外立面采用(双银LOW-E玻璃幕墙)","note":"项目整体历史配置","mult":1},{"lib":"071dd93a-b56d-509c-89fe-7b01f2e822b2","name":"丰科中心","pg":12,"hash":"1c478e7c5a7ebc4f60dfe3b4bd2b027887ba97a1a4ed567c84d531f2e7f4c7d2","f":"elevator_zones","type":"text","unit":"configuration","pat":"(设置高低分区)","note":"项目高低区配置，34部为各类型合计，不作为客梯数量","mult":1},{"lib":"071dd93a-b56d-509c-89fe-7b01f2e822b2","name":"丰科中心","pg":13,"hash":"1efb94aa255bb5e7f342eb1fe4ecf6b3bd0236b4b4a67fcf09b15466c28f669c","f":"delivery_standard","type":"text","unit":"configuration","pat":"(标准层办公区精装交付)","note":"历史标准层交付描述，不等于所有单元","mult":1},{"lib":"071dd93a-b56d-509c-89fe-7b01f2e822b2","name":"丰科中心","pg":15,"hash":"42682386c2f77e93480f814d7e5cb0d1929119185af23d34e0d43a5286af2da0","f":"column_free","type":"boolean","unit":"boolean","pat":"(无柱化办公空间)","note":"原项目宣传办公空间设计能力","mult":1}]$spec$::jsonb) v(lib uuid,pg int,hash text,name text,f text,type text,unit text,pat text,note text,mult numeric)), c AS (
 SELECT b.id bid,b.name,d.id target_id,v.f field_name,CASE v.type WHEN 'numeric' THEN to_jsonb(m.val::numeric*v.mult) WHEN 'integer' THEN to_jsonb(m.val::integer) WHEN 'boolean' THEN to_jsonb(true) ELSE to_jsonb(trim(regexp_replace(m.val,'[[:space:]]+',' ','g'))) END new_value,v.type value_type,'project_material_library' source_table,l.id source_id,'page:'||v.pg source_field,'internal_archived_page' source_kind,v.unit,v.note||'; page_sha256='||v.hash note
 FROM specs v JOIN project_material_library l ON l.id=v.lib JOIN project_material_library_pages p ON p.extraction_id=l.id AND p.page_number=v.pg AND p.content_sha256=v.hash JOIN buildings b ON b.name=v.name JOIN building_brochure_data d ON d.building_id=b.id CROSS JOIN LATERAL (SELECT (regexp_match(p.content->>'native_text',v.pat))[1] val) m
 WHERE l.review_state='reviewed' AND EXISTS(SELECT 1 FROM jsonb_array_elements(l.payload->'sections') s WHERE s->>'association_status'='confirmed' AND s->'candidate_building_ids' ? b.id::text AND jsonb_array_length(s->'candidate_building_ids')=1) AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(l.payload->'sections') s WHERE s->>'association_status' IS DISTINCT FROM 'confirmed' OR s->'candidate_building_ids' IS DISTINCT FROM jsonb_build_array(b.id::text))
 AND b.is_active AND b.city IN ('北京','北京市') AND b.tracking_scope='tracked' AND (b.project_type='stock' OR (b.project_type='future' AND b.is_entered_market=false)) AND b.merged_into_id IS NULL AND (SELECT count(*) FROM building_brochure_data y WHERE y.building_id=b.id)=1 AND to_jsonb(d)->v.f='null'::jsonb AND m.val IS NOT NULL
) SELECT c.* FROM c WHERE new_value IS NOT NULL AND NOT EXISTS(SELECT 1 FROM building_data_field_provenance p WHERE p.building_id=c.bid AND p.target_table='building_brochure_data' AND p.field_name=c.field_name) AND NOT EXISTS(SELECT 1 FROM audit_logs a WHERE a.action_type='AI_FIELD_FILL' AND a.target_table='building_brochure_data' AND a.target_id=c.target_id::text AND (a.details->>'field_name'=c.field_name OR a.new_values ? c.field_name)) ORDER BY target_id,field_name
 LOOP
  IF r.new_value IS NULL OR r.new_value='null'::jsonb OR r.value_type NOT IN ('text','integer','numeric','boolean','date') THEN RAISE EXCEPTION 'invalid candidate'; END IF;
  ev:=gen_random_uuid(); now_ts:=clock_timestamp();
  EXECUTE format('UPDATE public.building_brochure_data SET %I=($2#>>''{}'')::%s WHERE id=$1 AND building_id=$3 AND %I IS NULL',r.field_name,r.value_type,r.field_name) USING r.target_id,r.new_value,r.bid;
  GET DIAGNOSTICS changed=ROW_COUNT;
  IF changed<>1 THEN RAISE EXCEPTION 'null protection failed'; END IF;
  INSERT INTO public.building_data_field_provenance(building_id,brochure_data_id,target_table,field_name,field_value,source_type,source_tier,source_name,source_retrieved_at,value_recorded_at,verification_status,evidence_group_id,evidence_note,is_current)
  VALUES(r.bid,r.target_id,'building_brochure_data',r.field_name,r.new_value,CASE WHEN r.source_kind='internal_archived_page' THEN 'brochure' ELSE 'other' END,CASE WHEN r.source_kind='internal_archived_page' THEN 'secondary' ELSE 'legacy_unknown' END,CASE WHEN r.source_kind='internal_archived_page' THEN '高力国际已审阅历史项目资料' ELSE '高力国际内部已有业务记录' END,now_ts,now_ts,'legacy_backfill',ev,'batch_ref=ai_building_field_backfill_20261125_v5_100; source_table='||r.source_table||'; source_record_id='||r.source_id||'; source_field='||r.source_field||'; unit='||r.unit||'; '||r.note||'; AI-assisted',true);
  INSERT INTO public.audit_logs(id,user_id,action_type,details,request_source,module,target_table,target_id,target_name,old_values,new_values,event_id,occurred_at,actor_kind,actor_name)
  VALUES(nextval('public.audit_logs_id_seq'),'codex','AI_FIELD_FILL',jsonb_build_object('batch_ref','ai_building_field_backfill_20261125_v5_100','sub_batch',sub_batch,'building_id',r.bid,'field_name',r.field_name,'source_table',r.source_table,'source_record_id',r.source_id,'source_field',r.source_field,'source_kind',r.source_kind,'unit',r.unit,'verification_status','legacy_backfill','evidence_group_id',ev,'ai_assisted',true,'reversible',true),'codex_mcp','building_brochure_data','building_brochure_data',r.target_id::text,r.name,jsonb_build_object(r.field_name,NULL),jsonb_build_object(r.field_name,r.new_value),'ai_field_fill:'||ev::text,now_ts,'tool','Codex（工具执行）');
  EXECUTE format('SELECT to_jsonb(%I) FROM public.building_brochure_data WHERE id=$1',r.field_name) INTO read_value USING r.target_id;
  IF read_value IS DISTINCT FROM r.new_value OR NOT EXISTS(SELECT 1 FROM public.building_data_field_provenance p JOIN public.audit_logs a ON a.event_id='ai_field_fill:'||ev::text WHERE p.evidence_group_id=ev AND p.is_current AND p.field_value=read_value AND a.new_values->r.field_name=p.field_value AND a.old_values->r.field_name='null'::jsonb) THEN RAISE EXCEPTION 'readback failed'; END IF;
  n:=n+1;
 END LOOP;
 IF n<>expected_added THEN RAISE EXCEPTION 'expected % qualifying fields, got %',expected_added,n; END IF;
END $fill$;
SELECT count(*) cumulative,count(distinct (target_table,target_id,details->>'field_name')) unique_fields FROM public.audit_logs WHERE action_type='AI_FIELD_FILL' AND details->>'batch_ref'='ai_building_field_backfill_20261125_v5_100';
COMMIT;